}

Method.Source:
/// <summary>
/// MPJ_2864 - kscerri - 17/03/2021
/// Fills in the cust account num
/// </summary>
/// <param name="sender">Form Data Source</param>
/// <param name="e">Form data source event</param>
[
    FormDataSourceEventHandler(formDataSourceStr(CustTable, METCustTable), FormDataSourceEventType::ValidatingWrite),
    SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface')
]
public static void METCustTable_OnValidatingWrite(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun                 form            = sender.formRun();
    FormDataSource          custTable_ds    = form.dataSource(formDataSourceStr(CustTable,CustTable)) as FormDataSource;
    FormDataSource          metCustTable_ds = form.dataSource(formDataSourceStr(CustTable,METCustTable)) as FormDataSource;
    METCustTable            METCustTable    = metCustTable_ds.cursor();
    CustTable               CustTable       = custTable_ds.cursor();
    
    METCustTable.AccountNum = CustTable.AccountNum;
}
